rules:
:root[data-theme="classic-copy"] {
  --heading-weight: 600;
  --body-size: 16px;
  --line-height: 1.75;
  --radius: 4px;
}
[data-theme="classic-copy"] .markdown-body { max-width: 720px; }
[data-theme="classic-copy"] h1 { text-align: center; font-size: 2.2em; letter-spacing: 0.01em; border-bottom: 0; padding-bottom: 0; }
[data-theme="classic-copy"] h1::after { content: ""; display: block; width: 48px; height: 1px; margin: 0.5em auto 0; background: var(--accent); }
[data-theme="classic-copy"] h2 { font-style: italic; }
[data-theme="classic-copy"] blockquote { font-style: italic; border-left-width: 2px; }
[data-theme="classic-copy"] hr { height: 1px; width: 30%; margin: 2.4em auto; background: var(--accent); }
[data-theme="classic-copy"] th { background: transparent; border-bottom: 2px solid var(--accent); border-left: 0; border-right: 0; }
[data-theme="classic-copy"] td { border-left: 0; border-right: 0; }
[data-theme="classic-copy"] a { text-decoration: underline; text-underline-offset: 0.15em; text-decoration-thickness: 1px; }
[data-theme="classic-copy"] .hljs-keyword { font-weight: 650; }
[data-theme="classic-copy"] .hljs-title { font-weight: 650; }

variables:
:root[data-theme="classic-copy"] {
  --bg: #FCFCFB;
  --surface: #F2F2F0;
  --fg: #1C1C1C;
  --muted: #5E5E5E;
  --border: #DDDDDB;
  --heading: #111111;
  --accent: #2E2E2E;
  --link: #1C1C1C;
  --quote: #8C8C8C;
  --hl-keyword: #1C1C1C;
  --hl-string: #4D4D4D;
  --hl-comment: #6A6A6A;
  --hl-number: #3A3A3A;
  --hl-function: #1C1C1C;
  --hl-type: #3A3A3A;
  --mm-node: #F2F2F0;
  --mm-border: #5E5E5E;
  --mm-text: #1C1C1C;
  --mm-line: #6A6A6A;
  --mm-secondary: #EAEAE8;
  --mm-tertiary: #FCFCFB;
  --mm-note: #F6F6F3;
  --font-body: ui-serif, "New York", Georgia, "Songti TC", "Songti SC", serif;
}
@media (prefers-color-scheme: dark) {
  :root[data-theme="classic-copy"] {
  --bg: #171717;
  --surface: #222222;
  --fg: #E6E6E6;
  --muted: #A6A6A6;
  --border: #363636;
  --heading: #F2F2F2;
  --accent: #D4D4D4;
  --link: #EDEDED;
  --quote: #7C7C7C;
  --hl-keyword: #F2F2F2;
  --hl-string: #C4C4C4;
  --hl-comment: #9C9C9C;
  --hl-number: #D4D4D4;
  --hl-function: #F2F2F2;
  --hl-type: #D4D4D4;
  --mm-node: #262626;
  --mm-border: #A6A6A6;
  --mm-text: #E6E6E6;
  --mm-line: #9C9C9C;
  --mm-secondary: #202020;
  --mm-tertiary: #1B1B1B;
  --mm-note: #2B2B2B;
  }
}
